<span class="line"><span style="color:#24292E;">    </span><span style="color:#22863A;">url</span><span style="color:#24292E;">: </span><span style="color:#032F62;">jdbc:mysql://localhost:3306/db?useSSL=false&amp;serverTimezone=Asia/Shanghai</span></span>
